<script setup lang="ts">
import{computed,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import AppHeader from'../../components/AppHeader.vue';import StatusNotice from'../../components/StatusNotice.vue';import{api,apiRuntime}from'../../api/client';import{toOrderProjection,type ProjectProjection}from'../../api/project-contract';import{fromProjection}from'../../domain/price-snapshot';import{validateOrderSnapshot}from'../../domain/snapshot-flow';import{getOrCreateCommand}from'../../domain/command-identity';import type{OrderProjection}from'../../domain/types'
const p=ref<OrderProjection|null>(null),core=ref<ProjectProjection|null>(null),orderRef=ref(''),error=ref(''),loading=ref(false);const ready=computed(()=>validateOrderSnapshot(uni,orderRef.value,p.value?fromProjection(p.value):null));const canTopup=computed(()=>ready.value&&!!core.value?.allowedActions.some(a=>a.actionCode==='REQUEST_MOCK_TOPUP'));const finished=computed(()=>core.value?core.value.allowedActions.length===0&&core.value.facts.delivery==='CONFIRMED':p.value?.facts.delivery==='CONFIRMED');const title=computed(()=>finished.value?'充值已完成':core.value?.facts.upstreamDebit==='CONFIRMED'?'充值已提交，等待到账':'充值处理中')
async function refresh(){if(!orderRef.value)return;error.value='';try{if(apiRuntime.mode==='PROJECT_MOCK_API'){core.value=await api.getCoreProjection(orderRef.value);p.value=toOrderProjection(core.value)}else p.value=await api.getProjection(orderRef.value)}catch{error.value='暂时无法更新进度，我们会继续查询。'}}
async function completeTopup(){if(!canTopup.value||!core.value)return;loading.value=true;try{const c=getOrCreateCommand(uni,`mock-topup:${orderRef.value}`);core.value=await api.completeMockTopup(orderRef.value,c.commandId,c.idempotencyKey,core.value.projectionVersion,core.value.aggregateVersion,'CONFIRMED');p.value=toOrderProjection(core.value)}catch{error.value='充值结果暂时无法确认，我们会继续查询。'}finally{loading.value=false}}
onLoad(q=>{orderRef.value=typeof q?.orderRef==='string'?decodeURIComponent(q.orderRef):'';refresh()})
</script>
<template><view class="page"><AppHeader title="充值结果" left="订单" @left="uni.navigateBack()"/><view class="content result-page"><text class="result-mark" :class="{success:finished}">{{finished?'✓':'⌛'}}</text><view class="heading" role="heading" aria-level="1">{{title}}</view><text class="desc">{{finished?'充值结果已经确认':'你可以安全离开，稍后从“我的订单”查看最新结果。'}}</text><StatusNotice v-if="error" tone="unknown" title="暂时无法确认最新结果">{{error}}</StatusNotice><StatusNotice v-if="p&&!ready" tone="risk" title="信息已更新">当前不会重复付款或重复充值，请返回订单重新核对。</StatusNotice><view class="card summary"><view class="kv"><text>充值号码</text><text>{{p?.maskedPhone||'待确认'}}</text></view><view class="kv"><text>运营商</text><text>{{p?.operatorName||'待确认'}}</text></view><view class="kv"><text>支付金额</text><text>{{p?.total?.currency||''}} {{p?.total?(p.total.minor/100).toFixed(2):'待确认'}}</text></view></view></view><view class="action"><button v-if="apiRuntime.mode==='PROJECT_MOCK_API'&&canTopup" class="primary" :disabled="loading" @click="completeTopup">{{loading?'正在处理…':'继续处理'}}</button><button v-else-if="finished" class="primary" @click="uni.reLaunch({url:'/pages/index/index'})">完成</button><button v-if="!finished" class="secondary" @click="refresh">刷新进度</button></view></view></template><style src="../../styles/shared.css"></style><style scoped>.result-page{text-align:center;padding-top:70rpx}.result-mark{display:block;width:144rpx;height:144rpx;line-height:144rpx;margin:auto;border-radius:50%;background:#fff0d4;font-size:54rpx}.result-mark.success{background:#ddf3e9;color:var(--success);font-size:76rpx;font-weight:900}.result-page .heading{margin-top:26rpx}.summary{text-align:left;margin-top:50rpx}</style>
